[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --blue: #3861FB;
      --blue-light: #EEF2FF;
      --navy: #0D1421;
      --gray: #808A9D;
      --gray-light: #F8FAFD;
      --gray-border: #EFF2F5;
      --gray-bg: #F0F3F9;
      --green: #16c784;
      --green-bg: #eafaf3;
      --red: #ea3943;
      --red-bg: #fef2f3;
      --white: #ffffff;
      --text-primary: #0D1421;
      --text-secondary: #58667E;
      --text-muted: #A1A7BB;
    }

    html { font-size: 14px; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      background: var(--white);
      color: var(--text-primary);
      line-height: 1.5;
      min-height: 100vh;
    }

    /* ---- PROMO BANNER ---- */
    .promo-banner {
      background: var(--blue);
      color: white;
      text-align: center;
      padding: 8px 16px;
      font-size: 12px;
      font-weight: 500;
      position: relative;
      overflow: hidden;
    }
    .promo-banner .promo-slides { display: flex; transition: transform 0.5s ease; }
    .promo-banner .promo-slide { min-width: 100%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .promo-banner .promo-slide a { color: #fff; text-decoration: underline; margin-left: 6px; cursor: pointer; }
    .promo-banner .promo-nav {
      position: absolute; right: 12px; top: 50%; transform: translateY(-50%);
      display: flex; gap: 4px;
    }
    .promo-dot {
      width: 6px; height: 6px; border-radius: 50%; background: rgba(255,255,255,0.4);
      cursor: pointer; border: none; padding: 0;
    }
    .promo-dot.active { background: white; }

    /* ---- NAVBAR ---- */
    .navbar {
      background: white;
      border-bottom: 1px solid var(--gray-border);
      position: sticky; top: 0; z-index: 100;
    }
    .navbar-inner {
      max-width: 1440px; margin: 0 auto;
      display: flex; align-items: center; gap: 0;
      padding: 0 24px; height: 56px;
    }
    .navbar-brand {
      display: flex; align-items: center; gap: 8px;
      font-size: 18px; font-weight: 700; color: var(--blue);
      text-decoration: none; margin-right: 24px; white-space: nowrap;
      flex-shrink: 0;
    }
    .navbar-brand .logo-icon {
      width: 32px; height: 32px; background: var(--blue);
      border-radius: 8px; display: flex; align-items: center; justify-content: center;
    }
    .navbar-brand .logo-icon svg { fill: white; }
    .nav-links {
      display: flex; align-items: center; gap: 2px; flex: 1;
    }
    .nav-item {
      position: relative;
    }
    .nav-link {
      display: flex; align-items: center; gap: 4px;
      padding: 8px 12px; font-size: 13px; font-weight: 500;
      color: var(--text-secondary); text-decoration: none;
      border-radius: 6px; cursor: pointer; white-space: nowrap;
      background: none; border: none; transition: background 0.15s, color 0.15s;
    }
    .nav-link:hover, .nav-link.active { background: var(--gray-bg); color: var(--text-primary); }
    .nav-link svg { width: 12px; height: 12px; opacity: 0.6; }
    .nav-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }
    .btn-login {
      padding: 7px 16px; border: 1px solid var(--gray-border); border-radius: 8px;
      font-size: 13px; font-weight: 500; color: var(--text-primary);
      background: white; cursor: pointer; transition: background 0.15s;
    }
    .btn-login:hover { background: var(--gray-bg); }
    .btn-signup {
      padding: 7px 16px; border: 1px solid var(--blue); border-radius: 8px;
      font-size: 13px; font-weight: 500; color: white;
      background: var(--blue); cursor: pointer; transition: background 0.15s;
    }
    .btn-signup:hover { background: #2d4ed8; }

    /* ---- MARKET STATS BAR ---- */
    .stats-bar {
      background: white;
      border-bottom: 1px solid var(--gray-border);
      padding: 8px 24px;
    }
    .stats-bar-inner {
      max-width: 1440px; margin: 0 auto;
      display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
    }
    .stat-item {
      display: flex; align-items: center; gap: 6px;
      font-size: 12px; white-space: nowrap;
    }
    .stat-label { color: var(--text-muted); font-weight: 400; }
    .stat-value { color: var(--text-primary); font-weight: 600; font-variant-numeric: tabular-nums; }
    .stat-change { font-size: 11px; font-weight: 500; }
    .stat-change.up { color: var(--green); }
    .stat-change.down { color: var(--red); }
    .stat-change.neutral { color: var(--gray); }
    .stats-sep { width: 1px; height: 16px; background: var(--gray-border); }

    /* ---- AI ALERTS BAR ---- */
    .ai-bar {
      background: #F8FAFF;
      border-bottom: 1px solid var(--gray-border);
      padding: 9px 24px;
    }
    .ai-bar-inner {
      max-width: 1440px; margin: 0 auto;
      display: flex; align-items: center; gap: 12px; overflow-x: auto;
      scrollbar-width: none;
    }
    .ai-bar-inner::-webkit-scrollbar { display: none; }
    .ai-icon {
      display: flex; align-items: center; justify-content: center;
      width: 28px; height: 28px; background: var(--blue); border-radius: 6px;
      flex-shrink: 0;
    }
    .ai-icon svg { fill: white; width: 16px; height: 16px; }
    .ai-prompt {
      font-size: 12px; font-weight: 500; color: var(--text-primary);
      white-space: nowrap; flex-shrink: 0;
    }
    .ai-prompt span { color: var(--text-muted); font-weight: 400; }
    .ai-chips { display: flex; gap: 6px; flex-shrink: 0; }
    .ai-chip {
      padding: 4px 10px; background: white; border: 1px solid var(--gray-border);
      border-radius: 20px; font-size: 11px; color: var(--text-secondary);
      cursor: pointer; white-space: nowrap; transition: border-color 0.15s, color 0.15s;
    }
    .ai-chip:hover { border-color: var(--blue); color: var(--blue); }

    /* ---- MAIN CONTENT ---- */
    .main { max-width: 1440px; margin: 0 auto; padding: 24px 24px 0; }

    /* ---- PAGE HEADER ---- */
    .page-header { margin-bottom: 20px; }
    .page-title { font-size: 22px; font-weight: 700; color: var(--text-primary); margin-bottom: 4px; }
    .page-subtitle { font-size: 13px; color: var(--text-secondary); }

    /* ---- INDEX TRACKER ---- */
    .index-tracker {
      background: var(--gray-light);
      border: 1px solid var(--gray-border);
      border-radius: 10px;
      padding: 12px 16px;
      display: flex; align-items: center; gap: 20px;
      margin-bottom: 20px; flex-wrap: wrap;
    }
    .index-label { font-size: 12px; font-weight: 600; color: var(--text-secondary); white-space: nowrap; }
    .index-name { font-size: 13px; font-weight: 600; color: var(--blue); }
    .index-ticker { font-size: 11px; color: var(--text-muted); margin-left: 4px; }
    .index-price { font-size: 15px; font-weight: 700; font-variant-numeric: tabular-nums; }
    .index-changes { display: flex; gap: 16px; }
    .index-change-item { display: flex; align-items: center; gap: 4px; font-size: 12px; }
    .index-change-label { color: var(--text-muted); }

    /* ---- CATEGORY TABS ---- */
    .category-tabs {
      display: flex; align-items: center; gap: 4px;
      border-bottom: 2px solid var(--gray-border);
      margin-bottom: 16px;
    }
    .cat-tab {
      padding: 8px 16px; font-size: 13px; font-weight: 500;
      color: var(--text-secondary); cursor: pointer;
      border: none; background: none;
      border-bottom: 2px solid transparent; margin-bottom: -2px;
      transition: color 0.15s; white-space: nowrap;
    }
    .cat-tab:hover { color: var(--text-primary); }
    .cat-tab.active { color: var(--blue); border-bottom-color: var(--blue); font-weight: 600; }
    .cat-tab-more {
      padding: 8px 10px; display: flex; align-items: center; gap: 3px;
    }

    /* ---- NETWORK FILTER TABS ---- */
    .network-tabs {
      display: flex; align-items: center; gap: 6px;
      margin-bottom: 16px; flex-wrap: wrap;
    }
    .net-tab {
      display: flex; align-items: center; gap: 6px;
      padding: 6px 12px; border-radius: 20px;
      border: 1px solid var(--gray-border); background: white;
      font-size: 12px; font-weight: 500; color: var(--text-secondary);
      cursor: pointer; transition: all 0.15s; white-space: nowrap;
    }
    .net-tab:hover { border-color: var(--blue); color: var(--blue); }
    .net-tab.active { background: var(--blue); border-color: var(--blue); color: white; }
    .net-icon {
      width: 16px; height: 16px; border-radius: 50%;
      display: inline-flex; align-items: center; justify-content: center;
      font-size: 9px; font-weight: 700; color: white;
    }

    /* ---- TABLE CONTROLS ---- */
    .table-controls {
      display: flex; align-items: center; justify-content: space-between;
      margin-bottom: 12px; gap: 12px; flex-wrap: wrap;
    }
    .table-controls-left { display: flex; align-items: center; gap: 8px; }
    .table-controls-right { display: flex; align-items: center; gap: 8px; }
    .ctrl-btn {
      display: flex; align-items: center; gap: 5px;
      padding: 6px 12px; border-radius: 8px;
      border: 1px solid var(--gray-border); background: white;
      font-size: 12px; font-weight: 500; color: var(--text-secondary);
      cursor: pointer; transition: all 0.15s;
    }
    .ctrl-btn:hover, .ctrl-btn.active { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }
    .ctrl-btn svg { width: 13px; height: 13px; }
    .ctrl-sort {
      display: flex; align-items: center; gap: 5px;
      font-size: 12px; font-weight: 600; color: var(--blue);
      padding: 6px 12px; border-radius: 8px;
      background: var(--blue-light); border: 1px solid #c7d2fe;
      cursor: pointer;
    }

    /* ---- COLUMN TOGGLE PANEL ---- */
    .col-toggle-panel {
      background: white; border: 1px solid var(--gray-border);
      border-radius: 10px; padding: 16px;
      margin-bottom: 12px; display: none;
      grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 10px;
      box-shadow: 0 4px 16px rgba(0,0,0,0.08);
    }
    .col-toggle-panel.open { display: grid; }
    .col-toggle-item {
      display: flex; align-items: center; gap: 8px;
      font-size: 12px; color: var(--text-secondary); cursor: pointer;
    }
    .col-toggle-item input[type="checkbox"] { accent-color: var(--blue); width: 14px; height: 14px; }

    /* ---- FILTER PANEL ---- */
    .filter-panel {
      background: white; border: 1px solid var(--gray-border);
      border-radius: 10px; padding: 16px;
      margin-bottom: 12px; display: none;
      box-shadow: 0 4px 16px rgba(0,0,0,0.08);
    }
    .filter-panel.open { display: block; }
    .filter-panel-title { font-size: 13px; font-weight: 600; margin-bottom: 12px; }
    .filter-row { display: flex; gap: 12px; flex-wrap: wrap; }
    .filter-group { display: flex; flex-direction: column; gap: 6px; min-width: 140px; }
    .filter-group label { font-size: 11px; font-weight: 500; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.05em; }
    .filter-group select {
      padding: 6px 10px; border: 1px solid var(--gray-border); border-radius: 6px;
      font-size: 12px; color: var(--text-primary); background: white;
      font-family: inherit; cursor: pointer;
    }
    .filter-actions { display: flex; gap: 8px; margin-top: 12px; }
    .btn-apply {
      padding: 6px 14px; background: var(--blue); color: white;
      border: none; border-radius: 6px; font-size: 12px; font-weight: 500;
      cursor: pointer;
    }
    .btn-reset {
      padding: 6px 14px; background: white; color: var(--text-secondary);
      border: 1px solid var(--gray-border); border-radius: 6px; font-size: 12px; font-weight: 500;
      cursor: pointer;
    }

    /* ---- CRYPTO TABLE ---- */
    .table-wrap { overflow-x: auto; border: 1px solid var(--gray-border); border-radius: 12px; }
    .crypto-table {
      width: 100%; border-collapse: collapse; font-size: 13px;
    }
    .crypto-table thead tr {
      border-bottom: 1px solid var(--gray-border);
      background: var(--gray-light);
    }
    .crypto-table th {
      padding: 12px 16px; text-align: left;
      font-size: 11px; font-weight: 600; color: var(--text-muted);
      text-transform: uppercase; letter-spacing: 0.04em;
      white-space: nowrap; position: sticky; top: 0;
      background: var(--gray-light);
    }
    .crypto-table th.num { text-align: right; }
    .crypto-table th.sortable { cursor: pointer; user-select: none; }
    .crypto-table th.sortable:hover { color: var(--blue); }
    .crypto-table th.sorted { color: var(--blue); }
    .crypto-table th .sort-icon { margin-left: 4px; opacity: 0.5; }
    .crypto-table th.sorted .sort-icon { opacity: 1; }
    .crypto-table tbody tr {
      border-bottom: 1px solid var(--gray-border);
      transition: background 0.1s;
    }
    .crypto-table tbody tr:last-child { border-bottom: none; }
    .crypto-table tbody tr:hover { background: var(--gray-light); }
    .crypto-table td {
      padding: 12px 16px; vertical-align: middle;
      white-space: nowrap;
    }
    .crypto-table td.num {
      text-align: right;
      font-variant-numeric: tabular-nums;
      font-size: 13px;
    }
    .rank-num { font-size: 12px; color: var(--text-muted); font-weight: 500; width: 32px; display: inline-block; text-align: right; }
    .star-btn {
      background: none; border: none; cursor: pointer;
      color: var(--text-muted); font-size: 13px; padding: 0 4px;
      transition: color 0.15s;
    }
    .star-btn:hover { color: #f0a500; }
    .star-btn.starred { color: #f0a500; }

    .coin-cell { display: flex; align-items: center; gap: 10px; }
    .coin-icon {
      width: 28px; height: 28px; border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-size: 11px; font-weight: 700; color: white;
      flex-shrink: 0;
    }
    .coin-info {}
    .coin-name { font-size: 13px; font-weight: 600; color: var(--text-primary); }
    .coin-sym { font-size: 11px; color: var(--text-muted); font-weight: 500; }
    .price-cell { font-weight: 600; font-size: 13px; }
    .pct-up { color: var(--green); font-weight: 500; }
    .pct-down { color: var(--red); font-weight: 500; }
    .pct-neutral { color: var(--text-muted); font-weight: 500; }
    .supply-cell { font-size: 12px; color: var(--text-secondary); }
    .supply-bar { margin-top: 3px; height: 3px; background: var(--gray-border); border-radius: 2px; }
    .supply-fill { height: 100%; border-radius: 2px; background: var(--blue); opacity: 0.5; }

    /* Sparkline */
    .sparkline-cell { display: flex; align-items: center; justify-content: flex-end; }
    .sparkline { display: flex; align-items: flex-end; gap: 2px; height: 32px; }
    .spark-bar { width: 4px; border-radius: 2px 2px 0 0; min-height: 3px; }

    /* ---- PAGINATION ---- */
    .pagination-wrap {
      padding: 16px 20px;
      display: flex; align-items: center; justify-content: space-between;
      border-top: 1px solid var(--gray-border); flex-wrap: wrap; gap: 12px;
    }
    .pagination-info { font-size: 12px; color: var(--text-muted); }
    .pagination { display: flex; align-items: center; gap: 4px; }
    .page-btn {
      width: 32px; height: 32px; display: flex; align-items: center; justify-content: center;
      border: 1px solid var(--gray-border); border-radius: 6px;
      font-size: 12px; font-weight: 500; color: var(--text-secondary);
      cursor: pointer; background: white; transition: all 0.15s;
    }
    .page-btn:hover { border-color: var(--blue); color: var(--blue); }
    .page-btn.active { background: var(--blue); border-color: var(--blue); color: white; }
    .page-btn.disabled { opacity: 0.4; cursor: not-allowed; pointer-events: none; }
    .page-ellipsis { padding: 0 4px; color: var(--text-muted); font-size: 12px; }
    .rows-per-page {
      display: flex; align-items: center; gap: 8px;
      font-size: 12px; color: var(--text-muted);
    }
    .rows-per-page select {
      padding: 4px 8px; border: 1px solid var(--gray-border); border-radius: 6px;
      font-size: 12px; font-family: inherit; background: white; cursor: pointer;
    }

    /* ---- MARKET SUMMARY ---- */
    .market-summary {
      background: var(--gray-light); border: 1px solid var(--gray-border);
      border-radius: 12px; padding: 20px; margin: 24px 0;
    }
    .market-summary-title { font-size: 15px; font-weight: 700; margin-bottom: 8px; }
    .market-summary-text {
      font-size: 13px; color: var(--text-secondary); line-height: 1.7;
    }
    .market-summary-text strong { color: var(--text-primary); }
    .summary-extra { margin-top: 12px; display: none; }
    .summary-extra.open { display: block; }
    .read-more-btn {
      display: inline-flex; align-items: center; gap: 4px;
      margin-top: 8px; color: var(--blue); font-size: 12px; font-weight: 600;
      cursor: pointer; background: none; border: none; padding: 0;
    }
    .read-more-btn svg { width: 12px; height: 12px; transition: transform 0.2s; }
    .read-more-btn.open svg { transform: rotate(180deg); }

    /* ---- INFO SECTION ---- */
    .info-section { margin: 32px 0; }
    .info-section h2 { font-size: 18px; font-weight: 700; margin-bottom: 16px; }
    .info-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 20px; }
    .info-card {
      padding: 16px; background: var(--gray-light);
      border: 1px solid var(--gray-border); border-radius: 10px;
    }
    .info-card h3 { font-size: 13px; font-weight: 700; margin-bottom: 8px; }
    .info-card p { font-size: 12px; color: var(--text-secondary); line-height: 1.6; }

    /* ---- FOOTER ---- */
    footer {
      background: var(--navy); color: rgba(255,255,255,0.7);
      padding: 48px 24px 24px; margin-top: 48px;
    }
    .footer-inner { max-width: 1440px; margin: 0 auto; }
    .footer-top { display: flex; gap: 48px; flex-wrap: wrap; margin-bottom: 32px; }
    .footer-brand { flex: 0 0 220px; }
    .footer-brand .brand-name { font-size: 18px; font-weight: 700; color: white; margin-bottom: 8px; }
    .footer-brand p { font-size: 12px; line-height: 1.6; }
    .footer-cols { display: flex; gap: 48px; flex: 1; flex-wrap: wrap; }
    .footer-col h4 { font-size: 12px; font-weight: 700; color: white; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
    .footer-col a { color: rgba(255,255,255,0.6); text-decoration: none; font-size: 13px; transition: color 0.15s; }
    .footer-col a:hover { color: white; }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 20px; display: flex; align-items: center; justify-content: space-between;
      flex-wrap: wrap; gap: 12px;
    }
    .footer-copyright { font-size: 12px; }
    .footer-social { display: flex; gap: 12px; }
    .social-link {
      width: 32px; height: 32px; border-radius: 50%;
      background: rgba(255,255,255,0.1); display: flex; align-items: center; justify-content: center;
      color: rgba(255,255,255,0.7); text-decoration: none; font-size: 12px; font-weight: 700;
      transition: background 0.15s;
    }
    .social-link:hover { background: rgba(255,255,255,0.2); color: white; }

    /* ---- HIDDEN (column toggle) ---- */
    .col-1h, .col-7d, .col-supply, .col-volume, .col-mcap, .col-7dchart { }
    .hide-col-1h .col-1h { display: none; }
    .hide-col-7d .col-7d { display: none; }
    .hide-col-supply .col-supply { display: none; }
    .hide-col-volume .col-volume { display: none; }
    .hide-col-mcap .col-mcap { display: none; }
    .hide-col-7dchart .col-7dchart { display: none; }

    @media (max-width: 900px) {
      .navbar-inner { padding: 0 16px; gap: 8px; }
      .nav-links { display: none; }
      .main { padding: 16px 16px 0; }
      .stats-bar { padding: 8px 16px; }
      .ai-bar { padding: 9px 16px; }
    }
  </style>
</head>
<body>

<!-- PROMO BANNER -->
<div class="promo-banner" id="promoBanner">
  <div class="promo-slides" id="promoSlides">
    <div class="promo-slide">🚀 CTP Launch: Secure $GENIUS Airdrop — <a onclick="return false;">Join Now</a></div>
    <div class="promo-slide">✨ Featured: Solana DeFi Expansion — New pools live with 40%+ APY <a onclick="return false;">Explore Now</a></div>
    <div class="promo-slide">📊 CoinTracker Pro API: Millions of calls for live &amp; historic crypto data <a onclick="return false;">Get Access</a></div>
  </div>
  <div class="promo-nav" id="promoNav">
    <button class="promo-dot active" onclick="goPromo(0)"></button>
    <button class="promo-dot" onclick="goPromo(1)"></button>
    <button class="promo-dot" onclick="goPromo(2)"></button>
  </div>
</div>

<!-- NAVBAR -->
<nav class="navbar">
  <div class="navbar-inner">
